-- 192 · 24 BÀI NÓI B1 CHO CÂY LUYỆN TẬP (lô 38, 04/11).
--
-- Sinh bằng scripts/nhap/lo38_noi_b1.mjs, đừng sửa tay. Các dòng « Cần soạn » của B1-PO trong kế hoạch,
-- trừ hai bài thi thu nhỏ: 10 miễn phí, 14 VIP, 65 câu. Bài ghi âm có meta.ghiAm; B1-PO-3 (chuẩn bị
-- 10 phút) là bài viết có QCM. Audio câu hỏi B1-PO-1 ở nghe/b1-noi-*.mp3. Id tiền tố b1po.

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po01mxd01t', 'practice', 'Oral B1 : tes projets', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Écoutez les questions de l''examinateur (elles sont aussi écrites). Enregistrez-vous : répondez à chaque question en quatre ou cinq phrases, avec des détails et des exemples.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-noi-projets.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• en parallèle (expression) : song song\n• un stage (nom masculin) : kỳ thực tập\n• un domaine (nom masculin) : lĩnh vực\n• créer sa société (expression) : lập công ty riêng\n• avoir ses chances (expression) : có cơ hội","explications":"• Ở B1, mỗi câu trả lời nên có ý chính, lý do và một chi tiết cụ thể.\n• Dự định dùng conditionnel (j''aimerais, je voudrais) hoặc futur (ce sera).","ghiAm":true,"kyNang":"B1-PO-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-04T10:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw000', 'b1po01mxd01t', 1, 'open', 'Qu''est-ce que tu fais en ce moment : tu étudies ou tu travailles ?', '{}'::jsonb, '{"model":"En ce moment, je suis en deuxième année de master de commerce international à Hô Chi Minh-Ville. En parallèle, je fais un stage trois jours par semaine dans une entreprise qui exporte du café vers l''Europe. C''est assez fatigant, mais très intéressant."}'::jsonb, null), ('qmw1lximw001', 'b1po01mxd01t', 2, 'open', 'Pourquoi as-tu choisi ce domaine ?', '{}'::jsonb, '{"model":"J''ai choisi le commerce parce que j''aime le contact avec les gens et que je voulais un métier où on voyage. Mes parents ont une petite boutique, donc j''ai grandi au milieu des clients. Je crois que ça m''a donné envie de travailler dans ce domaine."}'::jsonb, null), ('qmw1lximw002', 'b1po01mxd01t', 3, 'open', 'Quels sont tes projets pour les prochaines années ?', '{}'::jsonb, '{"model":"Après mon master, j''aimerais travailler deux ou trois ans en France, dans une entreprise d''import-export. C''est pour ça que j''apprends le français. Ensuite, je voudrais revenir au Vietnam et peut-être créer ma propre société."}'::jsonb, null), ('qmw1lximw003', 'b1po01mxd01t', 4, 'open', 'Qu''est-ce qui pourrait t''empêcher de réaliser ce projet ?', '{}'::jsonb, '{"model":"Le plus difficile, ce sera sans doute de trouver un premier emploi en France sans expérience là-bas. Il y a aussi les papiers administratifs, comme le visa. Mais je pense qu''avec un bon niveau de français et un stage réussi, j''ai mes chances."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po02psr01u', 'practice', 'Oral B1 : une expérience marquante', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Écoutez les questions de l''examinateur (elles sont aussi écrites). Enregistrez-vous : répondez à chaque question en quatre ou cinq phrases, avec des détails et des exemples.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-noi-experience.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le bénévolat (nom masculin) : hoạt động tình nguyện\n• manquer (verbe) : thiếu\n• ému (adjectif) : xúc động\n• se contenter de peu (expression) : biết đủ với ít ỏi\n• semblable (adjectif) : tương tự","explications":"• Kể theo ba bước: chuyện gì xảy ra, cảm xúc lúc đó, điều học được.\n• Câu hỏi « Pourquoi ? » ở cuối là chỗ để nói thêm, đừng chỉ trả lời oui.","ghiAm":true,"kyNang":"B1-PO-1","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T10:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw004', 'b1po02psr01u', 1, 'open', 'Raconte-moi une expérience qui t''a marqué.', '{}'::jsonb, '{"model":"Il y a deux ans, j''ai fait du bénévolat pendant un mois dans une école d''un village de montagne, au nord du Vietnam. J''enseignais l''anglais à des enfants de huit à dix ans. Il n''y avait pas d''internet et l''eau chaude manquait souvent, mais l''ambiance était formidable."}'::jsonb, null), ('qmw1lximw005', 'b1po02psr01u', 2, 'open', 'Qu''est-ce que tu as ressenti à ce moment-là ?', '{}'::jsonb, '{"model":"Au début, j''étais un peu perdu, parce que je n''avais jamais enseigné et que les enfants parlaient surtout leur langue. Puis, petit à petit, je me suis senti utile. Le dernier jour, ils m''ont offert des dessins, et j''étais vraiment ému."}'::jsonb, null), ('qmw1lximw006', 'b1po02psr01u', 3, 'open', 'Qu''est-ce que cette expérience t''a appris ?', '{}'::jsonb, '{"model":"Elle m''a appris la patience, et aussi à me contenter de peu. En ville, on se plaint souvent pour de petites choses. Là-bas, les familles avaient très peu, mais elles partageaient tout avec moi."}'::jsonb, null), ('qmw1lximw007', 'b1po02psr01u', 4, 'open', 'Est-ce que tu aimerais vivre une expérience semblable ? Pourquoi ?', '{}'::jsonb, '{"model":"Oui, j''aimerais beaucoup recommencer, peut-être dans un pays francophone cette fois, comme le Sénégal. Ce serait l''occasion de pratiquer mon français et de découvrir une autre culture, tout en étant utile."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po03rjb01v', 'practice', 'Oral B1 : ton temps libre', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Écoutez les questions de l''examinateur (elles sont aussi écrites). Enregistrez-vous : répondez à chaque question en quatre ou cinq phrases, avec des détails et des exemples.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-noi-loisirs.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• occuper son temps (expression) : sử dụng thời gian\n• par hasard (expression) : tình cờ\n• dès que (conjonction) : ngay khi\n• bouger (verbe) : vận động\n• se détendre (verbe) : thư giãn","explications":"• Câu hỏi « si tu avais… » cần trả lời bằng conditionnel: j''apprendrais.\n• So sánh trước và nay: quand j''étais… (imparfait), maintenant… (présent).","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T10:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw008', 'b1po03rjb01v', 1, 'open', 'Comment est-ce que tu occupes ton temps libre ?', '{}'::jsonb, '{"model":"Pendant la semaine, j''ai peu de temps, alors je lis surtout le soir, avant de dormir. Le week-end, je fais de la randonnée avec un club, en général une fois par mois. Et le dimanche soir, je joue au badminton avec des collègues."}'::jsonb, null), ('qmw1lximw009', 'b1po03rjb01v', 2, 'open', 'Depuis quand pratiques-tu cette activité, et comment as-tu commencé ?', '{}'::jsonb, '{"model":"Je fais de la randonnée depuis trois ans. J''ai commencé un peu par hasard : une amie m''a proposé de l''accompagner à Sa Pa, et j''ai adoré marcher dans les montagnes. Depuis, j''essaie de partir dès que je peux."}'::jsonb, null), ('qmw1lximw00a', 'b1po03rjb01v', 3, 'open', 'Est-ce que tes loisirs ont changé depuis que tu es adulte ?', '{}'::jsonb, '{"model":"Oui, beaucoup. Quand j''étais adolescente, je passais des heures sur les jeux vidéo. Maintenant, je préfère les activités dehors, parce que je travaille toute la journée devant un ordinateur et que j''ai besoin de bouger."}'::jsonb, null), ('qmw1lximw00b', 'b1po03rjb01v', 4, 'open', 'Si tu avais plus de temps, qu''est-ce que tu aimerais apprendre ?', '{}'::jsonb, '{"model":"Si j''avais plus de temps, j''apprendrais la guitare. J''ai toujours admiré les gens qui jouent autour d''un feu pendant les randonnées. Et puis, je crois que la musique m''aiderait à me détendre après le travail."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po04ubp01w', 'practice', 'Oral B1 : parle-moi de toi', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Écoutez les questions de l''examinateur (elles sont aussi écrites). Enregistrez-vous : répondez à chaque question en quatre ou cinq phrases, avec des détails et des exemples.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-noi-portrait.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• curieux, curieuse (adjectif) : tò mò, ham hiểu biết\n• la veille (nom féminin) : hôm trước\n• têtu (adjectif) : bướng bỉnh\n• avoir tort (expression) : sai\n• l''honnêteté (nom féminin) : sự trung thực","explications":"• Câu hỏi xáo trộn đòi đổi thì nhanh: quá khứ (le week-end dernier), hiện tại, tương lai (dans dix ans).\n• Thêm một ví dụ nhỏ cho mỗi tính từ tự mô tả.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-1","vong":"on","thuTu":4}'::jsonb, '2026-11-04T10:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw00c', 'b1po04ubp01w', 1, 'open', 'Comment est-ce que tu te décrirais en quelques mots ?', '{}'::jsonb, '{"model":"Je dirais que je suis curieuse et assez organisée. J''aime comprendre comment les choses fonctionnent, et je prépare toujours mes journées la veille. Mes amis disent aussi que je suis têtue, et ils n''ont pas tout à fait tort !"}'::jsonb, null), ('qmw1lximw00d', 'b1po04ubp01w', 2, 'open', 'Où est-ce que tu as grandi, et qu''est-ce qui te manque de cet endroit ?', '{}'::jsonb, '{"model":"J''ai grandi à Hội An, une petite ville au centre du Vietnam. Aujourd''hui, j''habite à Hanoï. Ce qui me manque le plus, c''est le calme et la mer, et aussi la cuisine de ma grand-mère, bien sûr."}'::jsonb, null), ('qmw1lximw00e', 'b1po04ubp01w', 3, 'open', 'Qu''est-ce que tu as fait le week-end dernier ?', '{}'::jsonb, '{"model":"Samedi, je suis allée à une exposition de photographies sur l''ancien Hanoï. Ensuite, j''ai dîné avec des amis dans un restaurant de quartier. Dimanche, il pleuvait, donc je suis restée chez moi pour réviser mon français."}'::jsonb, null), ('qmw1lximw00f', 'b1po04ubp01w', 4, 'open', 'Quelle est la qualité que tu apprécies le plus chez un ami ?', '{}'::jsonb, '{"model":"Pour moi, la qualité la plus importante, c''est l''honnêteté. Je préfère un ami qui me dit la vérité, même si elle n''est pas agréable. Par exemple, une amie m''a dit un jour que mon projet n''était pas réaliste, et elle avait raison."}'::jsonb, null), ('qmw1lximw00g', 'b1po04ubp01w', 5, 'open', 'Où est-ce que tu te vois dans dix ans ?', '{}'::jsonb, '{"model":"Dans dix ans, j''espère avoir un travail stable dans le tourisme, peut-être dans une agence qui organise des voyages entre la France et le Vietnam. J''aimerais aussi avoir une maison près de la mer, pour retrouver le calme de mon enfance."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po05wph01x', 'practice', 'Oral B1 : l''entretien dirigé', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Comme à l''examen, l''entretien dirigé dure 2 à 3 minutes, sans préparation. L''examinateur vous vouvoie. Enregistrez-vous : répondez à chaque question de façon développée.</p>', null, 'https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/b1-noi-entretien.mp3', null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le génie civil (nom masculin) : xây dựng dân dụng\n• un chantier (nom masculin) : công trường\n• confier (verbe) : giao phó\n• un défi (nom masculin) : thử thách\n• accorder de l''importance à (expression) : coi trọng","explications":"• Phần 1 của đề thi không có thời gian chuẩn bị: luyện trước phần giới thiệu bản thân đến khi trôi chảy.\n• Giám khảo dùng vous: trả lời lịch sự, câu đầy đủ, không cụt.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-1","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T10:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw00h', 'b1po05wph01x', 1, 'open', 'Bonjour. Présentez-vous, s''il vous plaît.', '{}'::jsonb, '{"model":"Bonjour. Je m''appelle Trần Minh Đức, j''ai vingt-six ans et je suis vietnamien. J''habite à Đà Nẵng avec ma femme et notre fils de deux ans. Je suis ingénieur dans une entreprise de construction."}'::jsonb, null), ('qmw1lximw00i', 'b1po05wph01x', 2, 'open', 'Parlez-moi de votre parcours : vos études, votre travail.', '{}'::jsonb, '{"model":"J''ai fait des études de génie civil à l''université de Đà Nẵng. Après mon diplôme, j''ai d''abord travaillé sur des chantiers, puis on m''a confié la gestion de petits projets. Depuis un an, je travaille avec une entreprise française, c''est pourquoi j''ai commencé le français."}'::jsonb, null), ('qmw1lximw00j', 'b1po05wph01x', 3, 'open', 'Pourquoi avez-vous décidé de passer le DELF B1 ?', '{}'::jsonb, '{"model":"J''ai besoin d''un diplôme officiel pour mon entreprise, qui pourrait m''envoyer travailler six mois à Lyon. Mais c''est aussi un défi personnel : je voulais prouver que je pouvais apprendre une langue difficile en travaillant."}'::jsonb, null), ('qmw1lximw00k', 'b1po05wph01x', 4, 'open', 'Qu''est-ce que vous aimez dans la culture française, et qu''est-ce qui vous surprend ?', '{}'::jsonb, '{"model":"J''aime beaucoup l''importance que les Français accordent aux repas : on prend le temps de manger et de discuter. Ce qui me surprend, c''est qu''on parle souvent de politique, même avec des collègues, alors qu''au Vietnam on évite ce sujet."}'::jsonb, null), ('qmw1lximw00l', 'b1po05wph01x', 5, 'open', 'Comment imaginez-vous votre vie si vous partez vivre dans un pays francophone ?', '{}'::jsonb, '{"model":"Je pense que les premiers mois seraient difficiles, surtout pour mon fils et ma femme, qui ne parle pas encore français. Mais j''imagine une vie plus calme, avec des week-ends à la montagne. Ce serait une belle expérience pour toute la famille."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po06wph01y', 'practice', 'Oral B1 : le voisin est bruyant', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez la situation. Vous jouez votre rôle, l''examinateur joue l''autre personne. Pour chaque étape, enregistrez votre réplique : expliquez, argumentez, ne cédez pas tout de suite.</p>', '<p>Vous habitez dans un immeuble. Depuis deux semaines, votre voisin du dessus fait la fête jusqu''à deux heures du matin, plusieurs fois par semaine. Vous commencez le travail à sept heures. Vous allez le voir pour en parler. L''examinateur joue le rôle du voisin.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• déranger (verbe) : làm phiền\n• épuisé (adjectif) : kiệt sức\n• un compromis (nom masculin) : sự thoả hiệp\n• baisser (verbe) : vặn nhỏ, hạ\n• la compréhension (nom féminin) : sự thông cảm","explications":"• Phàn nàn lịch sự: excusez-moi de vous déranger, je comprends, mais…\n• Đừng chịu thua ngay khi bị phản đối: nêu hậu quả cụ thể rồi đưa đề xuất.","ghiAm":true,"kyNang":"B1-PO-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-04T10:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw00m', 'b1po06wph01y', 1, 'open', 'Présentez-vous et expliquez poliment le problème.', '{}'::jsonb, '{"model":"Bonsoir, excusez-moi de vous déranger. Je suis votre voisine du troisième, je m''appelle Lan. Je voulais vous parler du bruit : depuis deux semaines, j''entends de la musique jusqu''à deux heures du matin, plusieurs soirs par semaine."}'::jsonb, null), ('qmw1lximw00n', 'b1po06wph01y', 2, 'open', 'Le voisin répond qu''il a le droit de recevoir des amis chez lui. Expliquez les conséquences pour vous.', '{}'::jsonb, '{"model":"Bien sûr, vous avez le droit d''inviter vos amis, je ne dis pas le contraire. Mais je me lève à six heures pour aller travailler, et quand je dors seulement quatre heures, je suis épuisée toute la journée. Hier, j''ai même fait une erreur importante au bureau."}'::jsonb, null), ('qmw1lximw00o', 'b1po06wph01y', 3, 'open', 'Il dit qu''il ne peut pas faire moins de bruit. Proposez une solution.', '{}'::jsonb, '{"model":"Je comprends, mais on peut sûrement trouver un compromis. Par exemple, vous pourriez baisser la musique après vingt-deux heures, ou organiser vos fêtes le vendredi et le samedi, quand je ne travaille pas le lendemain. Et si vous mettez un tapis, on entendra moins les pas."}'::jsonb, null), ('qmw1lximw00p', 'b1po06wph01y', 4, 'open', 'Il accepte en partie. Trouvez un accord et terminez la conversation de façon aimable.', '{}'::jsonb, '{"model":"C''est très gentil, merci. Alors, on se met d''accord : les fêtes le week-end, et la musique moins forte après vingt-deux heures. Si un jour il y a un problème, je préfère venir vous en parler directement. Bonne soirée, et merci de votre compréhension !"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po07wph01z', 'practice', 'Oral B1 : convaincre tes parents', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez la situation. Vous jouez votre rôle, l''examinateur joue l''autre personne. Pour chaque étape, enregistrez votre réplique : expliquez, argumentez, ne cédez pas tout de suite.</p>', '<p>Cet été, vous voulez partir un mois au Maroc avec une association pour rénover une école. Vos parents ne sont pas d''accord. Vous essayez de les convaincre. L''examinateur joue le rôle de votre père ou de votre mère.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• rénover (verbe) : sửa sang, cải tạo\n• s''inquiéter (verbe) : lo lắng\n• économiser (verbe) : tiết kiệm\n• rassurer (verbe) : trấn an\n• c''est promis (expression) : hứa đấy","explications":"• Đoán trước ba phản đối (tiền, an toàn, việc học) và chuẩn bị câu trả lời cho từng cái.\n• Kết bằng một câu hỏi xin đồng ý: Alors, vous êtes d''accord ?","ghiAm":true,"kyNang":"B1-PO-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T10:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw00q', 'b1po07wph01z', 1, 'open', 'Présentez votre projet et dites pourquoi il est important pour vous.', '{}'::jsonb, '{"model":"Papa, maman, j''ai un projet pour cet été. Je voudrais partir un mois au Maroc avec l''association Mains ouvertes, pour aider à rénover une école dans un village. C''est important pour moi, parce que je veux être utile et découvrir une autre culture avant de commencer à travailler."}'::jsonb, null), ('qmw1lximw00r', 'b1po07wph01z', 2, 'open', 'Votre parent dit que c''est trop cher. Répondez.', '{}'::jsonb, '{"model":"Je sais que vous vous inquiétez pour l''argent, mais j''y ai pensé. L''association paie le logement et les repas. Il reste seulement le billet d''avion, et j''ai économisé six cents euros avec mon travail au café. Je ne vous demande rien."}'::jsonb, null), ('qmw1lximw00s', 'b1po07wph01z', 3, 'open', 'Il ou elle a peur pour votre sécurité. Rassurez-le ou rassurez-la.', '{}'::jsonb, '{"model":"Je comprends ta peur, mais l''association existe depuis quinze ans et elle organise ce séjour chaque été. Nous serons un groupe de douze jeunes, avec deux responsables. Et je vous appellerai tous les deux jours, c''est promis."}'::jsonb, null), ('qmw1lximw00t', 'b1po07wph01z', 4, 'open', 'Il ou elle dit que vous devez réviser pour vos examens. Proposez un compromis et concluez.', '{}'::jsonb, '{"model":"Tu as raison, mes examens de septembre sont importants. Je te propose ceci : je révise tout le mois de juin, et je pars seulement en juillet. En août, je serai à la maison pour finir mes révisions. Alors, vous êtes d''accord ? Ce serait vraiment une expérience inoubliable pour moi."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po08wph020', 'practice', 'Oral B1 : partager l''appartement', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez la situation. Vous jouez votre rôle, l''examinateur joue l''autre personne. Pour chaque étape, enregistrez votre réplique : expliquez, argumentez, ne cédez pas tout de suite.</p>', '<p>Vous partagez un appartement avec un ou une colocataire. Depuis un mois, c''est presque toujours vous qui faites le ménage et les courses. Vous voulez en parler et trouver une organisation plus juste. L''examinateur joue le rôle du ou de la colocataire.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un reproche (nom masculin) : lời trách\n• un petit boulot (nom masculin) : việc làm thêm\n• le partage (nom masculin) : sự chia sẻ\n• un planning (nom masculin) : lịch phân công\n• équilibré (adjectif) : cân bằng","explications":"• Thương lượng: nêu vấn đề không trách móc, đề xuất cụ thể, chấp nhận điều chỉnh nhỏ.\n• « Ça me va » là cách đồng ý tự nhiên khi bạn bè nói chuyện với nhau.","ghiAm":true,"kyNang":"B1-PO-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T10:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw00u', 'b1po08wph020', 1, 'open', 'Commencez la conversation et expliquez ce qui ne va pas.', '{}'::jsonb, '{"model":"Dis, tu as cinq minutes ? Je voudrais qu''on parle de l''organisation de l''appartement. Depuis un mois, j''ai l''impression de faire presque tout : le ménage, les courses, la vaisselle. Ce n''est pas un reproche, mais ça commence à me fatiguer."}'::jsonb, null), ('qmw1lximw00v', 'b1po08wph020', 2, 'open', 'Votre colocataire dit qu''il ou elle n''a pas le temps à cause de son travail. Répondez.', '{}'::jsonb, '{"model":"Je sais que tu travailles beaucoup en ce moment, mais moi aussi, j''ai mes cours et mon petit boulot. Ce n''est pas une question de temps, c''est une question de partage. Même une heure par semaine, ça changerait beaucoup de choses."}'::jsonb, null), ('qmw1lximw00w', 'b1po08wph020', 3, 'open', 'Proposez une nouvelle organisation.', '{}'::jsonb, '{"model":"Je propose qu''on fasse un planning. Par exemple, tu t''occupes des courses le samedi matin, puisque tu es libre, et moi je fais le ménage le dimanche. Pour la vaisselle, chacun lave la sienne tout de suite après le repas. Qu''est-ce que tu en penses ?"}'::jsonb, null), ('qmw1lximw00x', 'b1po08wph020', 4, 'open', 'Il ou elle veut changer un détail. Négociez et concluez.', '{}'::jsonb, '{"model":"D''accord, si tu préfères faire le ménage et que je fais les courses, ça me va aussi. L''important, c''est que ce soit équilibré. On essaie pendant un mois et on en reparle ? Super, merci, je suis contente qu''on ait trouvé une solution."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po09wpi021', 'practice', 'Oral B1 : un problème à l''hôtel', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez la situation. Vous jouez votre rôle, l''examinateur joue l''autre personne. Pour chaque étape, enregistrez votre réplique : expliquez, argumentez, ne cédez pas tout de suite.</p>', '<p>Vous êtes en vacances à Nice. Vous arrivez à l''hôtel le soir : votre chambre donne sur une rue très bruyante, la climatisation ne marche pas et la salle de bains n''est pas propre. Vous avez réservé une chambre calme. Vous allez à la réception. L''examinateur joue le rôle du réceptionniste.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• donner sur (verbe) : nhìn ra, hướng ra\n• correspondre à (verbe) : khớp với\n• complet (adjectif) : hết phòng\n• une réduction (nom féminin) : sự giảm giá\n• si j''ai bien compris (expression) : nếu tôi hiểu đúng","explications":"• Kết thúc bằng tóm lại thoả thuận: si j''ai bien compris… để tránh hiểu nhầm.\n• Từ chối đề nghị chưa đủ một cách lịch sự: c''est gentil, mais…","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-2","vong":"hoc","thuTu":4}'::jsonb, '2026-11-04T10:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw00y', 'b1po09wpi021', 1, 'open', 'Expliquez les problèmes au réceptionniste.', '{}'::jsonb, '{"model":"Bonsoir monsieur. Je suis madame Nguyen, chambre 208. Je suis désolée, mais la chambre ne correspond pas du tout à ma réservation. J''avais demandé une chambre calme, et elle donne sur une rue très bruyante. En plus, la climatisation ne fonctionne pas et la salle de bains est sale."}'::jsonb, null), ('qmw1lximw00z', 'b1po09wpi021', 2, 'open', 'Il répond que l''hôtel est complet. Insistez et demandez une solution.', '{}'::jsonb, '{"model":"Je comprends que l''hôtel soit complet, mais je ne peux pas rester dans ces conditions pendant cinq nuits. Il fait trente degrés dans la chambre. Est-ce que vous pourriez au moins envoyer quelqu''un pour réparer la climatisation et nettoyer la salle de bains ce soir ?"}'::jsonb, null), ('qmw1lximw010', 'b1po09wpi021', 3, 'open', 'Il propose une réduction de 10 %. Négociez.', '{}'::jsonb, '{"model":"C''est gentil, mais dix pour cent, ce n''est pas assez pour une chambre que je n''ai pas choisie. Je vous propose plutôt de me changer de chambre dès demain, quand d''autres clients partiront. Et pour ce soir, je voudrais le petit déjeuner offert."}'::jsonb, null), ('qmw1lximw011', 'b1po09wpi021', 4, 'open', 'Il accepte. Remerciez et vérifiez l''accord.', '{}'::jsonb, '{"model":"Très bien, merci beaucoup. Donc, si j''ai bien compris : la climatisation est réparée ce soir, je change de chambre demain à midi, et le petit déjeuner de demain est offert. Je vous remercie pour votre aide, bonne soirée."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po10wpi022', 'practice', 'Oral B1 : je veux être remboursé', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez la situation. Vous jouez votre rôle, l''examinateur joue l''autre personne. Pour chaque étape, enregistrez votre réplique : expliquez, argumentez, ne cédez pas tout de suite.</p>', '<p>Il y a dix jours, vous avez acheté un casque audio à 120 € dans un magasin. Il ne marche déjà plus. Vous voulez être remboursé, mais le magasin propose seulement un bon d''achat. L''examinateur joue le rôle du vendeur.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un casque audio (nom masculin) : tai nghe chụp\n• un bon d''achat (nom masculin) : phiếu mua hàng\n• défectueux (adjectif) : bị lỗi\n• la garantie (nom féminin) : bảo hành\n• au cas où (expression) : phòng khi","explications":"• Có lý lẽ thì nhắc quyền của mình: la garantie, avoir droit à.\n• Bị từ chối thì đưa phương án thứ hai, đừng lặp lại yêu cầu cũ.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-2","vong":"hoc","thuTu":5}'::jsonb, '2026-11-04T10:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw012', 'b1po10wpi022', 1, 'open', 'Expliquez le problème et dites ce que vous voulez.', '{}'::jsonb, '{"model":"Bonjour monsieur. J''ai acheté ce casque ici il y a dix jours, voici le ticket. Depuis hier, il ne marche plus du tout : il n''y a plus de son du côté gauche. Je voudrais être remboursé, s''il vous plaît."}'::jsonb, null), ('qmw1lximw013', 'b1po10wpi022', 2, 'open', 'Le vendeur propose un bon d''achat. Refusez poliment et expliquez pourquoi.', '{}'::jsonb, '{"model":"Merci, mais je ne veux pas de bon d''achat. Je n''ai besoin de rien d''autre dans votre magasin, et j''ai déjà perdu confiance dans ce modèle. Comme le produit est défectueux, je pense avoir droit à un remboursement."}'::jsonb, null), ('qmw1lximw014', 'b1po10wpi022', 3, 'open', 'Il dit que ce n''est pas possible. Insistez et proposez une autre solution.', '{}'::jsonb, '{"model":"Je comprends que ce soit la règle du magasin, mais la garantie est de deux ans. Si vous ne pouvez pas me rembourser, je veux bien un échange contre un autre modèle de la même marque, au même prix. Sinon, je devrai contacter le service client de la marque."}'::jsonb, null), ('qmw1lximw015', 'b1po10wpi022', 4, 'open', 'Il accepte l''échange. Concluez.', '{}'::jsonb, '{"model":"Parfait, je prends celui-ci, il me semble de meilleure qualité. Est-ce que vous pouvez noter l''échange sur mon ticket, au cas où il y aurait un nouveau problème ? Merci beaucoup pour votre aide, bonne journée."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po11wpi023', 'practice', 'Oral B1 : il refuse, que faire ?', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez la situation. Vous jouez votre rôle, l''examinateur joue l''autre personne. Pour chaque étape, enregistrez votre réplique : expliquez, argumentez, ne cédez pas tout de suite.</p>', '<p>Votre cousine se marie vendredi prochain à Lyon. Vous voulez prendre votre journée de vendredi, mais il y a beaucoup de travail cette semaine. Vous allez voir votre responsable. L''examinateur joue le rôle du ou de la responsable.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• prendre sa journée (expression) : xin nghỉ một ngày\n• prioritaire (adjectif) : ưu tiên\n• remplacer (verbe) : thay thế\n• joignable (adjectif) : liên lạc được\n• rattraper (verbe) : bù lại","explications":"• Bị từ chối hai lần là bình thường ở đề B1: mỗi lần đưa một phương án mới.\n• Hiểu lý do của người kia trước (je comprends tout à fait) rồi mới đề xuất.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-2","vong":"on","thuTu":6}'::jsonb, '2026-11-04T10:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw016', 'b1po11wpi023', 1, 'open', 'Faites votre demande et expliquez la raison.', '{}'::jsonb, '{"model":"Bonjour, vous avez un moment ? Je voulais vous demander si je pourrais prendre ma journée vendredi prochain. Ma cousine se marie à Lyon, et c''est très important pour ma famille. Je le sais seulement depuis hier, sinon je vous aurais prévenu plus tôt."}'::jsonb, null), ('qmw1lximw017', 'b1po11wpi023', 2, 'open', 'Le ou la responsable refuse : le projet doit être fini vendredi. Proposez une première solution.', '{}'::jsonb, '{"model":"Je comprends tout à fait, le projet est prioritaire. Je vous propose de rester plus tard mardi, mercredi et jeudi pour terminer ma partie avant vendredi. Comme ça, l''équipe aura tout ce qu''il faut."}'::jsonb, null), ('qmw1lximw018', 'b1po11wpi023', 3, 'open', 'Il ou elle refuse encore : il faut quelqu''un au bureau vendredi. Proposez une autre solution.', '{}'::jsonb, '{"model":"Dans ce cas, j''ai une autre idée. J''ai demandé à Thomas, il peut me remplacer vendredi matin. Et moi, je peux prendre le train de midi et travailler sur mon ordinateur pendant le trajet. Je resterai joignable par téléphone tout l''après-midi."}'::jsonb, null), ('qmw1lximw019', 'b1po11wpi023', 4, 'open', 'Il ou elle accepte avec une condition. Acceptez et remerciez.', '{}'::jsonb, '{"model":"Bien sûr, je vous enverrai un message vendredi midi pour faire le point avant de partir. Merci beaucoup de votre compréhension, ça me fait vraiment plaisir. Je rattraperai le temps la semaine prochaine si nécessaire."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po12wpi024', 'practice', 'Oral B1 : exercice en interaction', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Comme à l''examen : vous lisez la situation, puis vous jouez la scène pendant 3 ou 4 minutes, sans préparation. L''examinateur réagit à vos arguments.</p>', '<p>Vous voulez convaincre un ami français de suivre avec vous un cours de cuisine vietnamienne, le samedi matin pendant deux mois. Il n''est pas très motivé. L''examinateur joue le rôle de votre ami.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• ça te dirait de… ? (expression) : bạn có muốn… không?\n• faire la grasse matinée (expression) : ngủ nướng\n• justement (adverbe) : chính vì thế\n• en vouloir à quelqu''un (expression) : giận ai\n• marché conclu (expression) : thoả thuận nhé","explications":"• Trả lời từng phản đối một, bằng con số hoặc ví dụ cụ thể.\n• Đề nghị « thử một lần » là cách thuyết phục hiệu quả khi người kia còn do dự.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-2","vong":"chot","thuTu":7}'::jsonb, '2026-11-04T10:00:11.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw01a', 'b1po12wpi024', 1, 'open', 'Présentez le projet à votre ami de façon enthousiaste.', '{}'::jsonb, '{"model":"Dis, j''ai trouvé un cours génial ! C''est un cours de cuisine vietnamienne, le samedi matin, de dix heures à midi, pendant deux mois. On apprend à faire des nems, du phở, et même des desserts. Je pensais à toi, parce que tu adores les restaurants vietnamiens. Ça te dirait de venir avec moi ?"}'::jsonb, null), ('qmw1lximw01b', 'b1po12wpi024', 2, 'open', 'Il dit qu''il n''a pas le temps le samedi. Répondez.', '{}'::jsonb, '{"model":"Je sais que tu fais souvent la grasse matinée le samedi ! Mais le cours commence à dix heures, ce n''est pas si tôt. Et ce n''est que huit samedis. Tu pourrais faire tes courses l''après-midi, comme d''habitude."}'::jsonb, null), ('qmw1lximw01c', 'b1po12wpi024', 3, 'open', 'Il dit que c''est trop cher et qu''il ne sait pas cuisiner. Répondez à ces deux arguments.', '{}'::jsonb, '{"model":"Pour le prix, c''est cent vingt euros pour les huit cours, ingrédients compris. Ça fait quinze euros le cours, moins qu''un repas au restaurant ! Et justement, le cours est pour les débutants. Moi non plus, je ne sais pas cuisiner, c''est pour ça qu''on apprendrait ensemble."}'::jsonb, null), ('qmw1lximw01d', 'b1po12wpi024', 4, 'open', 'Il hésite encore. Faites une dernière proposition et concluez.', '{}'::jsonb, '{"model":"Écoute, je te propose de venir au premier cours, juste pour essayer. Si tu n''aimes pas, tu arrêtes, je ne t''en voudrai pas. Et si ça te plaît, à la fin, on organise un grand dîner vietnamien pour nos amis. Alors, marché conclu ?"}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po13wpi025', 'practice', 'Oral B1 : quel est le problème ?', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Vous avez dix minutes pour préparer l''exposé à partir du document. Ici, vous préparez par écrit : notez des mots-clés, pas un texte complet.</p>', '<p><strong>Toujours chez papa et maman à 28 ans</strong></p><p>Ils ont un diplôme, souvent un emploi, et pourtant ils vivent encore chez leurs parents. Selon une enquête récente, près d''un jeune adulte sur cinq habite toujours dans sa chambre d''enfant à l''approche de la trentaine. La raison principale : les loyers, qui ont fortement augmenté dans les grandes villes. Certains y voient une solidarité familiale positive ; d''autres s''inquiètent d''une génération qui devient autonome de plus en plus tard.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''approche de la trentaine (expression) : gần ba mươi tuổi\n• un loyer (nom masculin) : tiền thuê nhà\n• la solidarité (nom féminin) : sự tương trợ\n• autonome (adjectif) : tự lập\n• s''inquiéter (verbe) : lo lắng","explications":"• Vấn đề nên viết thành câu hỏi: Faut-il… ? Est-ce que… ? Giám khảo muốn nghe bạn nêu vấn đề trước.\n• Đừng tóm tắt tài liệu: chỉ lấy một con số làm ví dụ.","kyNang":"B1-PO-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-04T10:00:12.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximw01e', 'b1po13wpi025', 1, 'qcm', 'Quel est le problème posé par ce document ?', '{"options":["Faut-il s''inquiéter que les jeunes quittent leurs parents de plus en plus tard ?","Pourquoi les parents ont-ils de grandes maisons ?","Les jeunes ont-ils besoin d''un diplôme pour trouver un emploi ?"]}'::jsonb, '{"answer":0}'::jsonb, 'Tài liệu kết thúc bằng hai cách nhìn: « une solidarité familiale positive » và « une génération qui devient autonome de plus en plus tard ».'), ('qmw1lximx01f', 'b1po13wpi025', 2, 'qcm', 'Quelle information du document pouvez-vous utiliser comme exemple ou comme chiffre ?', '{"options":["les loyers ont baissé dans les grandes villes","près d''un jeune adulte sur cinq vit encore chez ses parents","la moitié des jeunes n''ont pas de diplôme"]}'::jsonb, '{"answer":1}'::jsonb, '« près d''un jeune adulte sur cinq habite toujours dans sa chambre d''enfant ».'), ('qmw1lximx01g', 'b1po13wpi025', 3, 'open', 'Écrivez le problème sous la forme d''une question, puis votre opinion en une phrase. (20 mots minimum)', '{}'::jsonb, '{"model":"Problème : est-ce grave de vivre chez ses parents après vingt-cinq ans ?\nMon opinion : ce n''est pas grave si c''est pour économiser, mais il faut un projet pour partir."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po14wpi026', 'practice', 'Oral B1 : deux idées, un exemple', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Vous avez dix minutes pour préparer l''exposé à partir du document. Ici, vous préparez par écrit : notez des mots-clés, pas un texte complet.</p>', '<p><strong>Apprendre en ligne : la fin de la salle de classe ?</strong></p><p>Cours de langue, de cuisine ou de programmation : on peut aujourd''hui presque tout apprendre devant son écran. Les plateformes promettent de la liberté, des prix bas et des professeurs du monde entier. Pourtant, beaucoup d''élèves abandonnent avant la fin. Sans camarades ni horaires fixes, il est difficile de rester motivé.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une plateforme (nom féminin) : nền tảng\n• promettre (verbe) : hứa hẹn\n• abandonner (verbe) : bỏ dở\n• un camarade (nom masculin) : bạn học\n• mélanger (verbe) : kết hợp","explications":"• Dàn ý chỉ ghi từ khoá: ở phòng thi bạn nói, không đọc.\n• Một ví dụ cá nhân giúp bài nói tự nhiên hơn mười câu chung chung.","kyNang":"B1-PO-3","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T10:00:13.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01h', 'b1po14wpi026', 1, 'qcm', 'Quel plan convient le mieux pour présenter votre opinion ?', '{"options":["Histoire de l''école ; prix des cours ; conclusion","Problème ; idée 1 : la liberté (exemple personnel) ; idée 2 : le manque de motivation ; conclusion : mélanger les deux formes","Résumé du document ; liste des plateformes ; conclusion"]}'::jsonb, '{"answer":1}'::jsonb, 'Phần 3 đề B1 cần: vấn đề, ý kiến có lý do và ví dụ, kết luận. Không tóm tắt tài liệu, không kể lịch sử.'), ('qmw1lximx01i', 'b1po14wpi026', 2, 'open', 'Écrivez votre plan en mots-clés : le problème, deux idées, un exemple, une conclusion. (30 mots minimum)', '{}'::jsonb, '{"model":"Problème : peut-on vraiment apprendre seul en ligne ?\nIdée 1 : liberté, horaires, prix. Exemple : mes cours de français le soir après le travail.\nIdée 2 : motivation difficile, pas de camarades, j''ai abandonné un cours de guitare en ligne.\nConclusion : en ligne + quelques cours en classe."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po15wpi027', 'practice', 'Oral B1 : dix minutes pour préparer', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Vous avez dix minutes pour préparer l''exposé à partir du document. Ici, vous préparez par écrit : notez des mots-clés, pas un texte complet.</p>', '<p><strong>Quatre jours d''école par semaine ?</strong></p><p>Dans plusieurs pays, des écoles primaires ont choisi la semaine de quatre jours : pas de classe le mercredi. Les parents qui travaillent doivent trouver une solution pour garder leurs enfants. Les enseignants, eux, sont divisés. Certains disent que les enfants sont moins fatigués ; d''autres pensent que les journées deviennent trop longues et que les élèves apprennent moins.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''école primaire (nom féminin) : trường tiểu học\n• garder (verbe) : trông (trẻ)\n• divisé (adjectif) : chia rẽ ý kiến\n• le rythme (nom masculin) : nhịp sinh hoạt\n• un neveu (nom masculin) : cháu trai","explications":"• Chia 10 phút: 2 phút đọc và tìm vấn đề, 6 phút dàn ý, 2 phút tập nói câu mở đầu.\n• Viết câu mở đầu đầy đủ là được, phần còn lại chỉ ghi từ khoá.","isPremium":true,"price":19000,"kyNang":"B1-PO-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T10:00:14.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01j', 'b1po15wpi027', 1, 'open', 'Préparez votre exposé en dix minutes : problème, plan avec deux ou trois idées, exemples, conclusion. Écrivez seulement des mots-clés. (40 mots minimum)', '{}'::jsonb, '{"model":"Problème : la semaine de quatre jours est-elle bonne pour les enfants ?\nIntroduction : document sur les écoles sans classe le mercredi.\nIdée 1 (pour) : repos au milieu de la semaine, activités sportives. Exemple : mon neveu fait du judo le mercredi.\nIdée 2 (contre) : journées trop longues, enfants fatigués le soir, parents qui travaillent.\nMon avis : plutôt contre, cinq journées plus courtes.\nConclusion : penser d''abord au rythme des enfants."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po16wpj028', 'practice', 'Oral B1 : préparez ce document', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Vous avez dix minutes pour préparer l''exposé à partir du document. Ici, vous préparez par écrit : notez des mots-clés, pas un texte complet.</p>', '<p><strong>Le livre papier résiste</strong></p><p>On annonçait sa disparition avec l''arrivée des liseuses et des tablettes. Pourtant, le livre papier reste largement préféré par les lecteurs. Beaucoup disent aimer son odeur, le plaisir de tourner les pages et de le prêter à un ami. Les défenseurs du numérique rappellent, eux, qu''une liseuse permet d''emporter des centaines de livres en vacances et coûte moins cher à long terme.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une liseuse (nom féminin) : máy đọc sách điện tử\n• largement (adverbe) : rộng rãi, phần lớn\n• prêter (verbe) : cho mượn\n• emporter (verbe) : mang theo\n• à long terme (expression) : về lâu dài","explications":"• Đề hai phía (papier / numérique): có thể chọn một bên hoặc dung hoà, miễn là nói rõ ý mình.\n• Kết luận ngắn, mở rộng nhẹ: l''important, c''est de lire.","isPremium":true,"price":19000,"kyNang":"B1-PO-3","vong":"on","thuTu":4}'::jsonb, '2026-11-04T10:00:15.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01k', 'b1po16wpj028', 1, 'open', 'Préparez votre exposé : problème, plan, exemples, conclusion. Écrivez seulement des mots-clés. (40 mots minimum)', '{}'::jsonb, '{"model":"Problème : livre papier ou livre numérique, lequel choisir ?\nIdée 1 : le papier, plaisir, pas d''écran le soir, prêter à des amis. Exemple : les livres de ma mère.\nIdée 2 : le numérique, pratique en voyage, moins cher, police plus grande.\nMon avis : les deux, papier à la maison, liseuse en voyage.\nConclusion : l''important, c''est de lire."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po17wpj029', 'practice', 'Oral B1 : deux documents, un choix', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Comme à l''examen, vous tirez deux documents et vous en choisissez un. Lisez-les, choisissez celui sur lequel vous avez le plus d''idées, puis préparez votre exposé en dix minutes.</p>', '<p><strong>Document A : Des villes sans publicité</strong></p><p>Une ville d''Amérique du Sud a retiré tous les panneaux publicitaires de ses rues. Ses habitants disent mieux voir leur ville. Les commerçants, eux, craignent de perdre des clients.</p><p><strong>Document B : Le sport obligatoire au travail ?</strong></p><p>Une entreprise impose à ses salariés trente minutes de sport par jour, pendant les heures de travail. Selon la direction, ils sont en meilleure santé et plus efficaces. Certains salariés trouvent pourtant que leur employeur se mêle de leur vie privée.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un panneau publicitaire (nom masculin) : biển quảng cáo\n• imposer (verbe) : áp đặt\n• efficace (adjectif) : hiệu quả\n• se mêler de (verbe) : xen vào\n• souple (adjectif) : linh hoạt","explications":"• Chọn tài liệu bạn có ví dụ cá nhân, không phải tài liệu có vẻ dễ hơn.\n• Ghi rõ document A hay B ở đầu, như ở phòng thi.","isPremium":true,"price":19000,"kyNang":"B1-PO-3","vong":"chot","thuTu":5}'::jsonb, '2026-11-04T10:00:16.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01l', 'b1po17wpj029', 1, 'open', 'Indiquez le document choisi, puis préparez votre exposé : problème, plan, exemples, conclusion. Écrivez seulement des mots-clés. (40 mots minimum)', '{}'::jsonb, '{"model":"Document choisi : B.\nProblème : une entreprise peut-elle obliger ses salariés à faire du sport ?\nIdée 1 : bon pour la santé et l''ambiance. Exemple : la pause badminton dans l''entreprise de mon frère.\nIdée 2 : obliger, non. Chacun choisit, vie privée, personnes malades ou fatiguées.\nMon avis : proposer, pas imposer.\nConclusion : encourager avec des horaires souples et une salle de sport."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po18wpj02a', 'practice', 'Oral B1 : le téléphone au lycée', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document et préparez-vous (dix minutes à l''examen). Enregistrez-vous : dégagez le problème posé, puis présentez votre opinion de façon claire et argumentée pendant 2 à 3 minutes.</p>', '<p><strong>Le portable bientôt interdit dans les lycées ?</strong></p><p>Après les écoles et les collèges, plusieurs lycées veulent interdire le téléphone portable, même pendant les récréations. Pour les directeurs, les élèves se parlent moins et sont moins concentrés en classe. Mais de nombreux lycéens protestent : ils ont presque dix-huit ans et estiment qu''ils doivent apprendre à gérer eux-mêmes leur téléphone.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une récréation (nom féminin) : giờ ra chơi\n• protester (verbe) : phản đối\n• gérer (verbe) : quản lý\n• rappeler à l''ordre (expression) : nhắc nhở\n• éduquer (verbe) : giáo dục","explications":"• Khuôn 4 bước: nêu vấn đề (la question est…), ý kiến, hai ba lý lẽ có ví dụ, kết luận.\n• Đừng đọc lại tài liệu: một câu giới thiệu là đủ, phần lớn thời gian dành cho ý kiến.","ghiAm":true,"kyNang":"B1-PO-4","vong":"hoc","thuTu":1}'::jsonb, '2026-11-04T10:00:17.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01m', 'b1po18wpj02a', 1, 'open', 'Dégagez le problème posé par ce document, puis présentez votre opinion avec des arguments et des exemples. (2 à 3 minutes)', '{}'::jsonb, '{"model":"Ce document parle de l''interdiction du téléphone portable dans les lycées, même pendant les pauses. La question est donc : faut-il interdire complètement le téléphone aux lycéens ?\nPersonnellement, je pense qu''une interdiction en classe est utile, mais qu''une interdiction totale va trop loin.\nD''abord, en classe, le téléphone est une vraie source de distraction. Quand j''étais au lycée, beaucoup d''élèves regardaient leurs messages pendant les cours, et les professeurs perdaient du temps à les rappeler à l''ordre. Interdire le téléphone pendant les cours, c''est donc protéger l''apprentissage.\nEnsuite, pendant les pauses, la situation est différente. Les lycéens sont presque adultes. S''ils ne peuvent jamais utiliser leur téléphone, ils n''apprendront pas à le gérer seuls. De plus, le téléphone est parfois nécessaire, par exemple pour prévenir ses parents d''un retard.\nEnfin, je crois qu''il vaudrait mieux éduquer que punir. Le lycée pourrait organiser des ateliers sur le bon usage des écrans.\nEn conclusion, je suis pour une règle claire en classe, mais contre une interdiction totale. C''est en apprenant à se limiter qu''on devient responsable."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po19wpj02b', 'practice', 'Oral B1 : prendre moins l''avion', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document et préparez-vous (dix minutes à l''examen). Enregistrez-vous : dégagez le problème posé, puis présentez votre opinion de façon claire et argumentée pendant 2 à 3 minutes.</p>', '<p><strong>Voyager sans avion, la nouvelle mode ?</strong></p><p>De plus en plus de voyageurs européens renoncent à l''avion pour leurs vacances. Ils préfèrent le train, le bus ou même le vélo, pour réduire leur impact sur le climat. Mais pour beaucoup de familles, ces voyages sont trop longs ou trop chers. Et pour aller sur un autre continent, l''avion reste souvent la seule solution.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• renoncer à (verbe) : từ bỏ\n• l''impact sur le climat (expression) : tác động tới khí hậu\n• une tendance (nom féminin) : xu hướng\n• réaliste (adjectif) : thực tế\n• accessible (adjectif) : vừa túi tiền, dễ tiếp cận","explications":"• Ý kiến có sắc thái (moins souvent, pas complètement) thường dễ bảo vệ hơn ý kiến tuyệt đối.\n• Premièrement, deuxièmement, enfin giúp giám khảo theo dõi lập luận.","ghiAm":true,"kyNang":"B1-PO-4","vong":"hoc","thuTu":2}'::jsonb, '2026-11-04T10:00:18.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01n', 'b1po19wpj02b', 1, 'open', 'Dégagez le problème posé par ce document, puis présentez votre opinion avec des arguments et des exemples. (2 à 3 minutes)', '{}'::jsonb, '{"model":"Ce document présente une tendance : certains voyageurs renoncent à l''avion pour protéger le climat. Le problème posé est le suivant : doit-on vraiment arrêter de prendre l''avion ?\nÀ mon avis, il faut le prendre moins souvent, mais il n''est pas réaliste de l''abandonner complètement.\nPremièrement, pour les courtes distances, le train est souvent une meilleure solution. Par exemple, l''été dernier, je suis allé de Paris à Marseille en train. Le trajet a duré trois heures, je suis arrivé en plein centre-ville et j''ai pu travailler pendant le voyage. En avion, avec l''aéroport, ça aurait pris presque autant de temps.\nDeuxièmement, pour les longues distances, l''avion reste nécessaire. Moi, par exemple, ma famille vit au Vietnam. Je ne peux pas faire ce voyage en bateau ou en train.\nEnfin, c''est aussi une question de prix. Les billets de train sont parfois plus chers que les vols à bas prix, et ce n''est pas normal. Les gouvernements devraient rendre le train plus accessible.\nPour conclure, je pense que chacun peut faire un effort, mais que les États doivent aider les voyageurs à choisir le train."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po20wpj02c', 'practice', 'Oral B1 : faut-il supprimer les notes ?', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document et préparez-vous (dix minutes à l''examen). Enregistrez-vous : dégagez le problème posé, puis présentez votre opinion de façon claire et argumentée pendant 2 à 3 minutes.</p>', '<p><strong>Une école sans notes</strong></p><p>Dans certaines écoles, les notes sur 20 ont été remplacées par des couleurs ou par des appréciations écrites. L''objectif : réduire le stress des élèves et les encourager plutôt que les classer. Mais certains parents regrettent de ne plus savoir précisément si leur enfant progresse, et des enseignants craignent que les élèves fassent moins d''efforts.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une appréciation (nom féminin) : lời nhận xét\n• classer (verbe) : xếp hạng\n• un repère (nom masculin) : mốc tham chiếu\n• où il en est (expression) : đang ở mức nào\n• accompagner (verbe) : đi kèm","explications":"• « D''un côté… d''un autre côté… » trình bày hai mặt trước khi chốt ý mình.\n• Kết luận có thể nêu điều nên thay đổi, không chỉ đồng ý hay phản đối.","ghiAm":true,"kyNang":"B1-PO-4","vong":"hoc","thuTu":3}'::jsonb, '2026-11-04T10:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01o', 'b1po20wpj02c', 1, 'open', 'Dégagez le problème posé par ce document, puis présentez votre opinion avec des arguments et des exemples. (2 à 3 minutes)', '{}'::jsonb, '{"model":"Ce document parle des écoles qui ont remplacé les notes par des couleurs ou des commentaires. La question est donc : faut-il supprimer les notes à l''école ?\nPour ma part, je pense que les notes sont utiles, mais qu''elles ne devraient pas être la seule évaluation.\nD''un côté, je comprends les écoles qui veulent réduire le stress. Quand j''étais au collège, j''avais très peur des contrôles de mathématiques. Une mauvaise note me décourageait pendant plusieurs jours, et je n''osais plus poser de questions.\nD''un autre côté, les notes donnent un repère clair. Un élève sait exactement où il en est, et les parents aussi. Par exemple, mon petit frère a eu des appréciations sans notes à l''école primaire, et mes parents ne comprenaient jamais s''il avait des difficultés.\nÀ mon avis, la meilleure solution serait de garder les notes, mais de toujours les accompagner d''un commentaire qui explique comment progresser. Ainsi, l''élève ne verrait pas seulement un chiffre, mais aussi un chemin.\nEn conclusion, supprimer les notes n''est pas nécessaire. Ce qu''il faut changer, c''est la manière de les utiliser."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po21wpj02d', 'practice', 'Oral B1 : manger moins de viande', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document et préparez-vous (dix minutes à l''examen). Enregistrez-vous : dégagez le problème posé, puis présentez votre opinion de façon claire et argumentée pendant 2 à 3 minutes.</p>', '<p><strong>Un jour sans viande à la cantine</strong></p><p>Dans de nombreuses cantines, un repas végétarien est désormais servi au moins une fois par semaine. Ses partisans rappellent que la production de viande pollue beaucoup et que l''on peut trouver des protéines dans les légumes secs. Ses opposants estiment que ces repas sont souvent moins bons et que chaque famille devrait pouvoir choisir ce que mangent ses enfants.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• hebdomadaire (adjectif) : hằng tuần\n• un partisan (nom masculin) : người ủng hộ\n• les légumes secs (nom masculin pluriel) : các loại đậu khô\n• varier son alimentation (expression) : ăn uống đa dạng\n• savoureux (adjectif) : ngon","explications":"• « À condition que + subjonctif » nêu điều kiện cho ý kiến của mình.\n• Nhắc lý lẽ của phe kia (je comprends les critiques) rồi trả lời nó.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-4","vong":"hoc","thuTu":4}'::jsonb, '2026-11-04T10:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01p', 'b1po21wpj02d', 1, 'open', 'Dégagez le problème posé par ce document, puis présentez votre opinion avec des arguments et des exemples. (2 à 3 minutes)', '{}'::jsonb, '{"model":"Le document présente le repas végétarien hebdomadaire dans les cantines. Il pose une question importante : faut-il manger moins de viande, et peut-on l''imposer aux enfants ?\nJe suis plutôt favorable à cette mesure, à condition que les repas soient bons.\nTout d''abord, il est vrai que nous mangeons trop de viande. Dans ma famille, au Vietnam, la viande était autrefois réservée aux jours de fête. Aujourd''hui, on en mange à chaque repas, et ce n''est bon ni pour la santé ni pour la planète.\nEnsuite, un repas végétarien par semaine, ce n''est pas beaucoup. Les enfants mangent de la viande les autres jours, et ils découvrent de nouveaux plats, avec des lentilles ou du tofu par exemple. C''est une façon de leur apprendre à varier leur alimentation.\nCependant, je comprends les critiques sur la qualité. Si le repas n''est pas bon, les enfants ne mangent rien et ont faim l''après-midi. Les cantines doivent donc former leurs cuisiniers et proposer des plats savoureux.\nEn conclusion, manger moins de viande est une bonne idée, mais il faut convaincre par le goût plutôt que par l''obligation."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po22wpj02e', 'practice', 'Oral B1 : travailler moins', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Lisez le document et préparez-vous (dix minutes à l''examen). Enregistrez-vous : dégagez le problème posé, puis présentez votre opinion de façon claire et argumentée pendant 2 à 3 minutes.</p>', '<p><strong>Et si on travaillait quatre jours par semaine ?</strong></p><p>Plusieurs entreprises testent la semaine de quatre jours, sans baisse de salaire. Les premiers résultats montrent des salariés moins stressés et aussi productifs qu''avant. Mais cette organisation est difficile dans les hôpitaux, les commerces ou les écoles, où il faut être présent tous les jours. Certains craignent aussi des journées plus longues et plus fatigantes.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une baisse de salaire (expression) : giảm lương\n• productif (adjectif) : năng suất\n• généraliser (verbe) : áp dụng rộng rãi\n• les démarches administratives (expression) : thủ tục hành chính\n• embaucher (verbe) : tuyển dụng","explications":"• « Pourtant, il faut reconnaître que… » đưa vào một giới hạn mà không đổi lập trường.\n• Ví dụ về người quen (une amie) là ví dụ hợp lệ ở phần thi này.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-4","vong":"hoc","thuTu":5}'::jsonb, '2026-11-04T10:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01q', 'b1po22wpj02e', 1, 'open', 'Dégagez le problème posé par ce document, puis présentez votre opinion avec des arguments et des exemples. (2 à 3 minutes)', '{}'::jsonb, '{"model":"Ce document parle des entreprises qui testent la semaine de quatre jours. La question posée est : faut-il généraliser cette organisation du travail ?\nJe pense que c''est une excellente idée pour beaucoup de métiers, mais pas pour tous.\nPremièrement, un jour libre de plus améliore la qualité de vie. On a du temps pour sa famille, pour le sport ou pour ses démarches administratives. Une amie qui travaille dans une agence de communication est passée à quatre jours l''année dernière. Elle dit qu''elle est beaucoup moins fatiguée et plus concentrée au bureau.\nDeuxièmement, cela peut être bon pour les entreprises. Des salariés reposés font moins d''erreurs et changent moins souvent d''emploi.\nPourtant, il faut reconnaître que ce modèle ne marche pas partout. Un hôpital ou une boulangerie ne peuvent pas fermer un jour par semaine. Dans ces métiers, il faudrait embaucher plus de personnel, ce qui coûte cher.\nPour conclure, je suis pour la semaine de quatre jours quand c''est possible, mais chaque secteur doit trouver sa propre solution."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po23wpj02f', 'practice', 'Oral B1 : sujet tiré au sort', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>À l''examen, le sujet est tiré au sort : vous ne le connaissez pas à l''avance. Lisez le document une seule fois, préparez-vous rapidement, puis enregistrez-vous pendant 2 à 3 minutes.</p>', '<p><strong>Les jeunes et le permis de conduire</strong></p><p>Dans les grandes villes, de moins en moins de jeunes passent le permis de conduire. Il coûte cher, il faut du temps pour le préparer, et beaucoup se déplacent en vélo, en trottinette ou en transports en commun. À la campagne, en revanche, le permis reste indispensable pour aller travailler ou étudier.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le permis de conduire (nom masculin) : bằng lái xe\n• une trottinette (nom féminin) : xe trượt scooter\n• se déplacer (verbe) : di chuyển\n• indispensable (adjectif) : không thể thiếu\n• les pouvoirs publics (nom masculin pluriel) : chính quyền","explications":"• Đề bốc ngẫu nhiên: luôn có sẵn khuôn câu mở (on peut donc se demander…) để không bị khựng.\n• So sánh hai nhóm (ville / campagne) là cách nhanh để có hai ý.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-4","vong":"on","thuTu":6}'::jsonb, '2026-11-04T10:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01r', 'b1po23wpj02f', 1, 'open', 'Dégagez le problème posé par ce document, puis présentez votre opinion avec des arguments et des exemples. (2 à 3 minutes)', '{}'::jsonb, '{"model":"Ce document explique que les jeunes des grandes villes passent de moins en moins le permis de conduire. On peut donc se demander : le permis est-il encore nécessaire pour les jeunes ?\nSelon moi, il reste utile, mais il n''est plus indispensable pour tout le monde.\nD''abord, en ville, on peut très bien vivre sans voiture. Moi, j''habite à Hanoï et je me déplace en bus et en moto-taxi. Une voiture me coûterait cher, et je passerais mon temps dans les embouteillages ou à chercher une place.\nEnsuite, le permis coûte très cher pour un étudiant. Je préfère dépenser cet argent pour un voyage ou pour une formation.\nCependant, la situation est différente à la campagne. Mes cousins, qui vivent loin de la ville, ont absolument besoin d''un véhicule pour aller au travail, car les bus passent rarement. Pour eux, le permis est une question de liberté.\nEn conclusion, je pense que chacun doit décider selon l''endroit où il vit. Mais les pouvoirs publics devraient aider les jeunes de la campagne à payer le permis, pour qu''ils aient les mêmes chances que les autres."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('b1po24wpj02g', 'practice', 'Oral B1 : expression d''un point de vue', 'B1', array['Production orale']::text[], 'practice', null, null, '<p>Comme à l''examen : dix minutes de préparation, puis 2 à 3 minutes d''exposé. Dégagez le problème, présentez votre opinion, donnez des exemples, concluez. L''examinateur pourrait ensuite vous poser des questions.</p>', '<p><strong>Faut-il interdire les voitures dans le centre des villes ?</strong></p><p>Plusieurs villes européennes ont fermé leur centre historique aux voitures. Les habitants profitent d''un air plus pur et de rues plus calmes, et les commerces attirent davantage de piétons. Mais les personnes âgées, les artisans et les habitants des villages voisins se plaignent : pour eux, venir en ville devient compliqué.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un centre historique (nom masculin) : khu phố cổ\n• un piéton (nom masculin) : người đi bộ\n• un artisan (nom masculin) : thợ thủ công\n• une alternative (nom féminin) : phương án thay thế\n• une navette (nom féminin) : xe đưa đón","explications":"• Sau bài nói, giám khảo thường hỏi lại: chuẩn bị sẵn một ví dụ dự phòng.\n• Câu kết nên nhắc lại lập trường bằng từ khác: Interdire sans proposer de solution serait injuste.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"B1-PO-4","vong":"chot","thuTu":7}'::jsonb, '2026-11-04T10:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmw1lximx01s', 'b1po24wpj02g', 1, 'open', 'Dégagez le problème posé par ce document, puis présentez votre opinion avec des arguments et des exemples. (2 à 3 minutes)', '{}'::jsonb, '{"model":"Ce document présente une décision prise par plusieurs villes : fermer le centre aux voitures. Le problème est le suivant : faut-il interdire la voiture dans le centre des villes ?\nJe suis plutôt pour cette idée, à condition de proposer de vraies alternatives.\nTout d''abord, les avantages sont évidents. Moins de voitures, c''est moins de pollution et moins de bruit. J''ai visité Pontevedra, en Espagne, où le centre est piéton : les enfants jouent dans la rue, les gens se promènent, et l''ambiance est très agréable.\nDe plus, contrairement à ce que pensent beaucoup de commerçants, les rues piétonnes attirent plus de clients. On s''arrête plus facilement devant une vitrine quand on marche que quand on conduit.\nCependant, il ne faut pas oublier ceux qui ont besoin d''une voiture : les personnes âgées, les artisans qui transportent du matériel ou les habitants de la campagne. Pour eux, la ville doit prévoir des parkings à l''entrée, des navettes gratuites et des autorisations spéciales.\nEn conclusion, je pense qu''un centre sans voitures est une bonne chose, si la ville reste accessible à tous. Interdire sans proposer de solution serait injuste."}'::jsonb, null)) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

do $$
declare b int; c int; g int;
begin
  select count(*) into b from public.exercises where id like 'b1po%';
  select count(*) into c from public.questions where exercise_id like 'b1po%';
  select count(*) into g from public.exercises where id like 'b1po%' and (meta->>'ghiAm')::boolean is true;
  if b <> 24 or c <> 65 or g <> 19 then raise exception 'lô 38: % bài, % câu, % bài ghi âm (cần 24, 65, 19)', b, c, g; end if;
end $$;
